# First, let me load all demo pairs and test input
import os, re, json

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, w_cols = m[1], int(m[2])
        rows = []
        got_rows = False
        for line in t[m.end():].split('\n'):
            if re.match(r'\d', line):
                got_rows = True
                continue
            if got_rows:
                parts = [int(x) for x in line.split()]
                if all(0 <= p <= 9 for p in parts):
                    rows.append(parts)
                    if len(rows) == int(m[3]):
                        break
        if k not in G and rows and len(rows) == int(m[3]) and all(len(r) == int(m[2]) for r in rows):
            G[k] = rows
    return G

